<?php
declare(strict_types=1);
require_once dirname(__DIR__) . '/bootstrap.php';
use School\Core\SchoolAuth;
use School\Core\SchoolDatabase;
use School\Services\AuditService;

SchoolAuth::requireLogin();$user=SchoolAuth::user();$role=school_current_role($user);if(!SchoolAuth::hasPermission('students.manage')){http_response_code(403);exit('Student registration is not permitted.');}
$pdo=SchoolDatabase::connection();$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!SchoolAuth::verifyCsrf())$error='Your session expired. Please try again.';
 else{
  $admission=trim((string)($_POST['admission_number']??''));$name=trim((string)($_POST['full_name']??''));$dob=(string)($_POST['date_of_birth']??'');$gender=(string)($_POST['gender']??'undisclosed');$admitted=(string)($_POST['admission_date']??date('Y-m-d'));$classId=(int)($_POST['class_group_id']??0);$streamId=(int)($_POST['stream_id']??0);$guardianUserId=(int)($_POST['guardian_user_id']??0);$relationship=trim((string)($_POST['relationship']??'Parent/Guardian'));
  if($admission===''||$name===''||!in_array($gender,['female','male','other','undisclosed'],true))$error='Enter an admission number, full name, and valid gender.';
  else try{
   $newId=SchoolDatabase::transaction(function(PDO $pdo)use($admission,$name,$dob,$gender,$admitted,$classId,$streamId,$guardianUserId,$relationship,$user):int{
    $yearId=null;if($classId){$q=$pdo->prepare('SELECT academic_year_id FROM class_groups WHERE id=:class');$q->execute(['class'=>$classId]);$yearId=$q->fetchColumn();if(!$yearId)throw new RuntimeException('Choose a valid class.');if($streamId){$q=$pdo->prepare('SELECT COUNT(*) FROM streams WHERE id=:stream AND class_group_id=:class');$q->execute(['stream'=>$streamId,'class'=>$classId]);if(!(int)$q->fetchColumn())throw new RuntimeException('The selected stream does not belong to that class.');}}
    if($guardianUserId){$q=$pdo->prepare("SELECT COUNT(*) FROM user_roles ur JOIN roles r ON r.id=ur.role_id JOIN users u ON u.id=ur.user_id WHERE u.id=:user AND u.status='active' AND r.name='parent_guardian'");$q->execute(['user'=>$guardianUserId]);if(!(int)$q->fetchColumn())throw new RuntimeException('Select an active Parent / Guardian account.');}
    $q=$pdo->prepare("INSERT INTO students (admission_number,full_name,date_of_birth,gender,admission_date,status) VALUES (:admission,:name,:dob,:gender,:admitted,'active')");$q->execute(['admission'=>$admission,'name'=>$name,'dob'=>$dob!==''?$dob:null,'gender'=>$gender,'admitted'=>$admitted]);$studentId=(int)$pdo->lastInsertId();
    if($yearId){$q=$pdo->prepare("INSERT INTO enrollments (student_id,academic_year_id,class_group_id,stream_id,status,started_at) VALUES (:student,:year,:class,:stream,'active',:started)");$q->execute(['student'=>$studentId,'year'=>(int)$yearId,'class'=>$classId,'stream'=>$streamId?:null,'started'=>$admitted]);}
    if($guardianUserId){$q=$pdo->prepare("INSERT INTO guardians (user_id,relationship_label) VALUES (:user,:relationship) ON DUPLICATE KEY UPDATE relationship_label=VALUES(relationship_label)");$q->execute(['user'=>$guardianUserId,'relationship'=>$relationship]);$q=$pdo->prepare('SELECT id FROM guardians WHERE user_id=:user');$q->execute(['user'=>$guardianUserId]);$guardianId=(int)$q->fetchColumn();$q=$pdo->prepare("INSERT INTO student_guardians (student_id,guardian_id,relationship,verification_status,verified_by,verified_at) VALUES (:student,:guardian,:relationship,'verified',:actor,UTC_TIMESTAMP())");$q->execute(['student'=>$studentId,'guardian'=>$guardianId,'relationship'=>$relationship,'actor'=>(int)$user['id']]);}
    (new AuditService())->record((int)$user['id'],'student.create','students',$studentId,['admission_number'=>$admission]);return $studentId;
   });
   school_flash('success','Student record created.');header('Location: '.SCHOOL_BASE_URL.'students/index.php');exit;
  }catch(Throwable $exception){$error=$exception instanceof PDOException?'That admission number is already in use.':$exception->getMessage();}
 }
}
$classes=$pdo->query('SELECT c.id,c.name,c.level,y.name year_name,y.id year_id FROM class_groups c JOIN academic_years y ON y.id=c.academic_year_id ORDER BY y.starts_on DESC,c.name')->fetchAll();
$streams=$pdo->query('SELECT id,class_group_id,name FROM streams ORDER BY name')->fetchAll();
$guardians=$pdo->query("SELECT u.id,u.full_name,u.username FROM users u JOIN user_roles ur ON ur.user_id=u.id JOIN roles r ON r.id=ur.role_id WHERE r.name='parent_guardian' AND u.status='active' ORDER BY u.full_name")->fetchAll();
$schoolName=(string)($pdo->query('SELECT name FROM school_profile ORDER BY id LIMIT 1')->fetchColumn()?:'School Management');$schoolRole=$role;$pageTitle='Register student';
require __DIR__.'/../includes/header.php';
?>
<div class="page-head"><div><h4>Register student</h4><p>Create a student record and optionally place them in a class and link a verified guardian.</p></div><div class="page-actions"><a href="<?= SCHOOL_BASE_URL ?>students/index.php" class="btn btn-outline-secondary btn-sm"><i class="bi bi-arrow-left me-1"></i>Student register</a></div></div>
<?php if($error!==''): ?><div class="alert alert-danger"><?= e($error) ?></div><?php endif; ?>
<div class="row g-3"><div class="col-xl-8"><div class="card"><div class="card-header"><span class="card-title-sm"><i class="bi bi-person-plus me-1"></i>Student details</span></div><div class="card-body"><form method="post" class="row g-3"><?= SchoolAuth::csrfField() ?>
<div class="col-md-6"><label class="form-label">Admission number</label><input class="form-control" name="admission_number" maxlength="40" value="<?= e($_POST['admission_number']??'') ?>" required></div><div class="col-md-6"><label class="form-label">Full name</label><input class="form-control" name="full_name" maxlength="180" value="<?= e($_POST['full_name']??'') ?>" required></div>
<div class="col-md-4"><label class="form-label">Date of birth</label><input class="form-control" name="date_of_birth" type="date" value="<?= e($_POST['date_of_birth']??'') ?>"></div><div class="col-md-4"><label class="form-label">Gender</label><select class="form-select" name="gender"><option value="undisclosed">Prefer not to say</option><option value="female">Female</option><option value="male">Male</option><option value="other">Other</option></select></div><div class="col-md-4"><label class="form-label">Admission date</label><input class="form-control" name="admission_date" type="date" value="<?= e($_POST['admission_date']??date('Y-m-d')) ?>" required></div>
<div class="col-md-6"><label class="form-label">Class and academic year</label><select class="form-select" name="class_group_id" id="classGroup"><option value="0">Add without class placement</option><?php foreach($classes as $class): ?><option value="<?= (int)$class['id'] ?>"><?= e($class['year_name'].' · '.$class['name'].' ('.ucfirst($class['level']).')') ?></option><?php endforeach; ?></select><?php if(!$classes): ?><div class="form-text">Configure academic years and classes first.</div><?php endif; ?></div><div class="col-md-6"><label class="form-label">Stream (optional)</label><select class="form-select" name="stream_id" id="streamSelect"><option value="0">No stream</option><?php foreach($streams as $stream): ?><option data-class="<?= (int)$stream['class_group_id'] ?>" value="<?= (int)$stream['id'] ?>"><?= e($stream['name']) ?></option><?php endforeach; ?></select></div>
<div class="col-12"><hr><h6>Guardian link</h6><p class="small text-muted">A school administrator confirms this relationship when registering it.</p></div><div class="col-md-6"><label class="form-label">Parent / Guardian account</label><select class="form-select" name="guardian_user_id"><option value="0">Do not link now</option><?php foreach($guardians as $guardian): ?><option value="<?= (int)$guardian['id'] ?>"><?= e($guardian['full_name'].' · '.($guardian['username']??'')) ?></option><?php endforeach; ?></select></div><div class="col-md-6"><label class="form-label">Relationship</label><input class="form-control" name="relationship" value="Parent/Guardian" maxlength="60"></div>
<div class="col-12"><button class="btn btn-primary"><i class="bi bi-check2-circle me-1"></i>Save student</button></div></form></div></div></div><div class="col-xl-4"><div class="card"><div class="card-header"><span class="card-title-sm"><i class="bi bi-shield-check me-1"></i>Record access</span></div><div class="card-body small text-muted">Only school users with student management permission can register students. Parent access is linked to the guardian account selected here and checked on every student query.</div></div></div></div>
<script>document.getElementById('classGroup').addEventListener('change',function(){const cid=this.value;const select=document.getElementById('streamSelect');Array.from(select.options).forEach((o,i)=>{if(i>0)o.hidden=o.dataset.class!==cid;});select.value='0';});</script>
<?php require __DIR__.'/../includes/footer.php'; ?>
